<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue'
import { useRoute } from 'vue-router'
import { get } from '../api/client'
import { type Entity, type Page, type Related, title, entityLink } from '../types/catalog'
const route = useRoute(), works = ref<Entity[]>([]), a = ref(String(route.query.animeA || '')), b = ref(String(route.query.animeB || '')), error = ref(''), loading = ref(false)
interface Group { items: Related[]; total: number; returned: number; truncated: boolean }
const common = ref<Record<string, Group>>()
const labels: Record<string, string> = { people: '共同制作人员', characters: '共同出场角色', voiceActors: '共同声优（作品范围内）' }
let controller: AbortController | undefined
async function compare() { controller?.abort(); controller = new AbortController(); const current = controller; loading.value = true; error.value = ''; common.value = undefined; try { const data = await get<Record<string, Group>>(`/analysis/common?${new URLSearchParams({ animeA: a.value, animeB: b.value })}`, current.signal);if(!current.signal.aborted)common.value=data } catch(e) { if (!current.signal.aborted) error.value = e instanceof Error ? e.message : '查询失败' } finally { if (!current.signal.aborted) loading.value = false } }
onMounted(async () => { try { works.value = (await get<Page<Entity>>('/anime?pageSize=100')).items; a.value ||= works.value[0]?.uid || ''; b.value ||= works.value[1]?.uid || '' } catch(e) { error.value = e instanceof Error ? e.message : '读取失败' } }); onUnmounted(() => controller?.abort())
</script>
<template><section class="page-intro"><p class="eyebrow">COMPARE & CONNECT</p><h1>两部作品，有什么联系？</h1><p>分别核对制作人员、出场角色和作品内声优。角色之间的跨作品联系请使用独立的角色联系探索。</p></section><form class="toolbar" @submit.prevent="compare"><label class="grow">作品 A<select v-model="a" required><option v-for="w in works" :key="w.uid" :value="w.uid">{{ title(w) }}</option></select></label><label class="grow">作品 B<select v-model="b" required><option v-for="w in works" :key="w.uid" :value="w.uid">{{ title(w) }}</option></select></label><button class="primary" :disabled="loading || !a || !b">比较作品</button></form><p v-if="error" class="feedback error" role="alert">{{ error }}</p><p v-if="loading" class="feedback" role="status">正在核对共同项…</p><template v-if="common"><section v-for="(group, key) in common" :key="key" class="panel"><h2>{{ labels[key] }} <small>· {{ group.total < 0 ? group.returned + '+' : group.total }}</small></h2><p v-if="group.truncated" class="notice">当前列表已截断，仅展示前 {{ group.returned }} 项。</p><p v-if="!group.items.length" class="muted">没有符合条件的共同实体。</p><div v-if="group.items.length" class="table-scroll"><table><caption>{{ labels[key] }}</caption><thead><tr><th scope="col">名称</th><th scope="col">作品 A / B 记录</th></tr></thead><tbody><tr v-for="row in group.items" :key="row.entity.uid"><td><RouterLink :to="entityLink(row.entity)">{{ title(row.entity) }} ↗</RouterLink></td><td><span v-if="row.rolesA">A：{{ row.rolesA.join('、') }} / B：{{ row.rolesB?.join('、') }}</span><span v-else-if="'charactersA' in row">作品内角色证据已匹配</span><span v-else>已匹配共同实体</span></td></tr></tbody></table></div></section></template></template>
